#!/usr/bin/env node
/**
 * Concatenates the tracker's source modules into the production bundle.
 *
 * The plugin loads `assets/js/dist/bahoosh-tracker.js` unless SCRIPT_DEBUG is
 * on, so a change to `assets/js/core/*.js` has no effect on a real site until
 * this runs. That is a sharp edge — the file that was edited is not the file
 * that ships — and it is why this script lives in the repository rather than on
 * someone's laptop, and why packaging refuses to build when the two disagree.
 *
 * Load order is the numeric filename prefix, the same rule
 * BAP_WordPress::tracker_modules() uses when SCRIPT_DEBUG is on, so development
 * and production load the same modules in the same order.
 */

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const outFile = path.join(root, "assets/js/dist/bahoosh-tracker.js");

function modules() {
  const read = (dir) =>
    fs
      .readdirSync(path.join(root, dir))
      .filter((name) => name.endsWith(".js"))
      .sort()
      .map((name) => path.join(dir, name));

  return [...read("assets/js/core"), ...read("assets/js/integrations")];
}

function build() {
  const files = modules();
  const version = (fs.readFileSync(path.join(root, "bahoosh-analytics-pro.php"), "utf8").match(
    /define\(\s*'BAP_VERSION',\s*'([^']+)'/
  ) || [])[1];

  const header = [
    "/**",
    " * Bahoosh Analytics Pro — tracker bundle.",
    " *",
    ` * Generated by tools/build-bundle.js for plugin version ${version}.`,
    " * Do not edit: change the modules in assets/js/core/ and rebuild.",
    " */",
    "",
  ].join("\n");

  const body = files
    .map((file) => `/* ---- ${file} ---- */\n${fs.readFileSync(path.join(root, file), "utf8").trim()}\n`)
    .join("\n");

  return { contents: `${header}${body}`, files };
}

const { contents, files } = build();

if (process.argv.includes("--check")) {
  const current = fs.existsSync(outFile) ? fs.readFileSync(outFile, "utf8") : "";
  if (current !== contents) {
    console.error("Bundle is stale. Run: node tools/build-bundle.js");
    process.exit(1);
  }
  console.log(`Bundle is current (${files.length} modules).`);
  process.exit(0);
}

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, contents);
console.log(`Wrote ${path.relative(root, outFile)} from ${files.length} modules.`);
